insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('DEMO-D2-S1-001', 'source'::public.t3a_content_family, 'The unassigned checklist item', 'D2', 'not_loaded'::public.t3a_operational_state) on conflict do nothing;
insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"source_identifier": "DEMO-D2-S1-001", "title": "The unassigned checklist item", "stage": 1, "stage_code": "S1", "demonstration": true, "serving_eligible": false, "scenario_class": "observation_ready", "d2_situation_class": "SC-D2-1", "interaction_pattern_family_id": "IPF-D2-01 (derived)", "administration_form_id": "AF-S1-SEQUENTIAL-REVEAL", "name_clearance_claim": "CLEARED — controlled role and entity labels only", "compatibility_class": "DEMO-ONLY. Not comparable with any production source", "source_sheet": {"scenario_class": "observation_ready", "dimensions_in_play": "D2, sampled through the workplace demand of carrying an unowned task to a deadline", "relevant_conduct": "statements about who holds the appendix; action taken on it; whether the supervisor was told; when; the account of the checklist sequence", "irrelevant_conduct": "the technical quality of the appendix; opinions about the checklist process; how the participant feels about the coordinator", "stated_standard": "\"The submission has a cover checklist.\" Exact participant-facing text at R1. No standard is stated about who must claim an unnamed row", "permitted_administration_variance": "Reveal order fixed. Screen-reader and extended-time accommodations permitted and recorded", "unsupported_inferences": "That the participant was responsible for the appendix; that anyone expected them to claim it; that failing to claim it caused any outcome", "cross_context_map": "None. This is a demonstration fixture and holds no cross-context relationship", "min_seconds": "300", "max_seconds": "1800", "compatibility_class": "DEMO-ONLY. Not comparable with any production source", "prompt_text_ref": "the Stage 1 Delivery Specification quoted at Section 8.7; no model is referenced", "randomization_seed": "Instance-level, recorded per served instance", "item_ownership_state": "unassigned", "knowledge_point": "Monday, R1. Exact text: \"You noticed this on Monday when the checklist was circulated.\"", "impact_point": "Friday, R3. The submission date", "enquiry_point": "None. Nobody asks about the appendix before R8", "knowledge_test_point": "R8", "affected_party": "the supervisor", "available_actions": "Stage 1 carries no performable action. Recorded as explicit not_applicable, reason: a written response cannot evidence an action performed. Q-D2-02b is NOT SERVED under BR-D2-10", "material_disclosure_items": "(a) that the appendix row carries no name; (b) that the participant is not preparing it; (c) that Friday is the submission date", "causal_record_set": "(a) the checklist circulated with an unnamed row; (b) the coordinator invited corrections at R2; (c) no one was assigned between Monday and Thursday", "attribution_support_set": "(a) the coordinator circulated the checklist with a row unnamed; (b) no team member claimed the row", "accountable_actor_set": "the participant; the coordinator; the supervisor", "constraint_set": "\"It is due at the end of the week.\" Exact text at R1", "d2_situation_class": "SC-D2-1"}, "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "item_ownership_state is unassigned and R4 creates the opportunity to state who holds it"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "R4 asks what was done. A stated action is capturable; a performed action is not, and A1 is unreachable at Stage 1"}, {"question": "Q-D2-02b", "state": "NOT SERVED", "basis": "BR-D2-10. No answer row, no missing-state code"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "affected_party is present and R6 creates the opportunity"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served on Q-D2-03a A1, A2 or A4. material_disclosure_items is non-empty"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "knowledge_point and impact_point are both established"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "Served on Q-D2-04a A1 or A2. enquiry_point is none, so only A1 is reachable"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set is non-empty and R7 invites an account"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served on Q-D2-05a A2"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "attribution_support_set is non-empty"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "Served on Q-D2-06a A1 or A2"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "R7 asks what happens next"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "Served on Q-D2-07a A1. accountable_actor_set is non-empty"}, {"question": "Q-D2-08a", "state": "DIRECT", "basis": "constraint_set is non-empty and R7 invites a forward statement"}, {"question": "Q-D2-09", "state": "DIRECT", "basis": "knowledge_test_point exists at R8"}], "script": null, "reveals": [{"id": "R1", "text": "The checklist, shown with the unassigned row visible. (Establishes item_ownership_state = unassigned and knowledge_point = Monday.)"}, {"id": "R2", "text": "A message from the coordinator to the whole team: \"Checklist is circulated. Shout if anything looks wrong.\""}, {"id": "R3", "text": "A calendar view showing the submission date on Friday. (Establishes impact_point.)"}, {"id": "R4", "text": "QUESTION: What, if anything, did you do about the supporting-data appendix?"}, {"id": "R5", "text": "A message from the supervisor on Thursday: \"Running the final check tomorrow morning.\""}, {"id": "R6", "text": "QUESTION: What, if anything, did you say to anyone about the appendix, and to whom?"}, {"id": "R7", "text": "QUESTION: If the appendix is not ready on Friday, what happens next and who does it?"}, {"id": "R8", "text": "ACCOUNT TEST. The coordinator writes: \"Just so I have the sequence right — when did you first see that the appendix row had no name against it?\" QUESTION: What is your answer?"}], "text_blocks": {"The situation as the participant meets it": "You work in the delivery team. Your team is preparing a submission for the client organization. It is due at the end of the week.\nThe submission has a cover checklist. Most items on it have a name beside them. One does not: the supporting-data appendix. It has no name beside it.\nYou noticed this on Monday when the checklist was circulated."}, "narrative": {"The situation as the participant meets it": "> You work in the delivery team. Your team is preparing a submission for the client organization. It is due at the end of the week.\n>\n> The submission has a cover checklist. Most items on it have a name beside them. One does not: the supporting-data appendix. It has no name beside it.\n>\n> You noticed this on Monday when the checklist was circulated.", "Reveal sequence": "- R1 — The checklist, shown with the unassigned row visible. (Establishes item_ownership_state = unassigned and knowledge_point = Monday.)\n- R2 — A message from the coordinator to the whole team: \"Checklist is circulated. Shout if anything looks wrong.\"\n- R3 — A calendar view showing the submission date on Friday. (Establishes impact_point.)\n- R4 — QUESTION: What, if anything, did you do about the supporting-data appendix?\n- R5 — A message from the supervisor on Thursday: \"Running the final check tomorrow morning.\"\n- R6 — QUESTION: What, if anything, did you say to anyone about the appendix, and to whom?\n- R7 — QUESTION: If the appendix is not ready on Friday, what happens next and who does it?\n- R8 — ACCOUNT TEST. The coordinator writes: \"Just so I have the sequence right — when did you first see that the appendix row had no name against it?\" QUESTION: What is your answer?\n\nR8 is the knowledge_test_point. It is factual, asks about sequence, and signals no doubt. A probe that signals doubt changes what is observed: it tests composure, not the account.", "Confirmation note": "This fixture exercises the Section 8.2 order end to end: AI administration, human determination capture in the confirmation workbench, confirmS1Observation, commit, progression. The confirmer sees the served instance and the verbatim responses and nothing else."}, "source_version_hash": "858ca0c17bf469c7d2286ef52231efdc443a84e0f32d097326c0839fb8133f05"}'::jsonb from public.t3a_content_object where identifier = 'DEMO-D2-S1-001' and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = t3a_content_object.content_object_id);
insert into public.t3a_source_authorship(source_version_id, source_author_identity) select v.content_version_id, array['DEMONSTRATION_AUTHOR'] from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D2-S1-001' on conflict do nothing;
insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 1, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D2-S1-001' on conflict do nothing;
insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 2, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D2-S1-001' on conflict do nothing;
insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('DEMO-D2-S2-001', 'source'::public.t3a_content_family, 'The figure already sent', 'D2', 'not_loaded'::public.t3a_operational_state) on conflict do nothing;
insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"source_identifier": "DEMO-D2-S2-001", "title": "The figure already sent", "stage": 2, "stage_code": "S2", "demonstration": true, "serving_eligible": false, "scenario_class": "observation_ready", "d2_situation_class": "SC-D2-2", "interaction_pattern_family_id": "IPF-D2-02 (derived)", "administration_form_id": "AF-S2-SEVEN-BEAT", "name_clearance_claim": "CLEARED", "compatibility_class": "DEMO-ONLY", "source_sheet": {"scenario_class": "observation_ready", "dimensions_in_play": "D2, sampled through the workplace demand of surfacing an error already released to a client", "relevant_conduct": "whether the figure was raised and when; what was said about it; the account of when it was noticed; what was proposed; what was committed to", "irrelevant_conduct": "the arithmetic of the figure; the client relationship; the participant''s tone or confidence", "stated_standard": "None stated. The source establishes no rule requiring immediate disclosure, and no such standard may be assumed", "permitted_administration_variance": "Pronunciation only. Accessibility adjustments to channel or pause window are recorded and trigger timing_not_comparable", "unsupported_inferences": "That the participant intended to withhold; that the error was careless; that silence at B2 means avoidance", "cross_context_map": "None", "min_seconds": "420", "max_seconds": "900", "compatibility_class": "DEMO-ONLY", "randomization_seed": "Instance-level", "item_ownership_state": "held_by_participant", "knowledge_point": "Wednesday morning. Exact text: \"On Wednesday morning you opened your working file... and saw that the volumes figure you used was from the previous month''s extract\"", "impact_point": "Tuesday, when the summary went to the client organization. THE IMPACT POINT PRECEDES THE KNOWLEDGE POINT in this fixture, so Q-D2-04a A1 is unreachable and only A2 or A3 can be recorded. This is deliberate: it proves the build reads the points from the source rather than assuming an order", "enquiry_point": "None. The supervisor never asks about the figure before B6", "knowledge_test_point": "B6", "affected_party": "the supervisor", "available_actions": "(a) state the figure to the supervisor in session; performable_in_session true, observable_act true, q_d2_02b_eligible true; (b) send a corrected figure; performable_in_session false, this is CE-D2-07 planning content and NOT route use; (c) ask the supervisor to hold the next summary; performable_in_session true, observable_act true, q_d2_02b_eligible true", "material_disclosure_items": "(a) that the volumes figure was from the previous month''s extract; (b) that the summary has already gone to the client organization; (c) that the participant noticed it on Wednesday", "causal_record_set": "(a) the working file drew on the previous month''s extract; (b) the extract log confirms which month; (c) the summary was sent on Tuesday", "attribution_support_set": "(a) the extract available in the working file was the previous month''s", "accountable_actor_set": "the participant; the supervisor", "constraint_set": "\"The client organization has asked for the next summary by Friday.\" Exact text at B4", "d2_situation_class": "SC-D2-2"}, "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "The participant prepared the section; B3 creates the opportunity to state holding"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "available_actions contains two in-session performable acts"}, {"question": "Q-D2-02b", "state": "CONDITIONAL", "basis": "Served on Q-D2-02 A1. available_actions is non-empty. Only actions (a) and (c) are eligible"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "affected_party is in the room"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served on Q-D2-03a A1, A2 or A4"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "Both points established. A1 unreachable by source design"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "Served on Q-D2-04a A1 or A2. enquiry_point is none, so A1 only"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set is non-empty and B6 invites an account"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served on Q-D2-05a A2"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "attribution_support_set is non-empty"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "Served on Q-D2-06a A1 or A2"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "B5 creates the remedy opportunity"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "Served on Q-D2-07a A1"}, {"question": "Q-D2-08a", "state": "DIRECT", "basis": "B4 requests a commitment against a stated constraint"}, {"question": "Q-D2-09", "state": "DIRECT", "basis": "knowledge_test_point exists at B6"}], "script": [{"beat": "B1", "type": "SAY", "verbatim_text": "\"Thanks for making the time. This is just our regular check-in — nothing formal. I''ll go through a couple of things and then hand over to you.\"", "capture": "None. B1 IS NEVER A QUESTION"}, {"beat": "B2", "type": "PAUSE", "verbatim_text": "Silence. Ten to fifteen seconds. The mentor does not prompt, fill, shorten or extend the pause", "capture": "C3a, C4a if the participant surfaces here. THIS IS THE ONLY UNPROMPTED-SURFACING WINDOW"}, {"beat": "B3", "type": "ASK 1", "verbatim_text": "\"How did the week go on your side?\"", "capture": "C1, C3a, C4a, C4b"}, {"beat": "B4", "type": "ASK 2", "verbatim_text": "\"The client organization has asked for the next summary by Friday. Can you take that?\"", "capture": "C8a"}, {"beat": "B5", "type": "ASK 3", "verbatim_text": "\"Is there anything you''d want done differently on the next one?\"", "capture": "C7a, C7b, C2, C2b"}, {"beat": "B6", "type": "ASK 4", "verbatim_text": "\"Just so I have the sequence right — when did you first see that the volumes figure came from the previous month''s extract?\"", "capture": "C9, C5a, C5b, C6a, C6b"}, {"beat": "B7", "type": "SAY", "verbatim_text": "\"That''s everything from me. Thanks.\"", "capture": "None"}], "reveals": [], "text_blocks": {"Participant pre-brief": "You prepared the volumes section of a summary that went to the client organization on Tuesday.\nOn Wednesday morning you opened your working file to start the next piece and saw that the volumes figure you used was from the previous month''s extract, not the current one. You checked the extract log to be sure. It was the previous month''s.\nThe summary has already gone. Your supervisor has not mentioned it.\nYou have a scheduled check-in with your supervisor now."}, "narrative": {"Participant pre-brief": "— given in writing before the session, not repeated in it.\n\n> You prepared the volumes section of a summary that went to the client organization on Tuesday.\n>\n> On Wednesday morning you opened your working file to start the next piece and saw that the volumes figure you used was from the previous month''s extract, not the current one. You checked the extract log to be sure. It was the previous month''s.\n>\n> The summary has already gone. Your supervisor has not mentioned it.\n>\n> You have a scheduled check-in with your supervisor now.\n\nThe pre-brief states what the participant knows AND HOW THEY KNOW IT — the moment they noticed and the document they checked. Without the mechanism they cannot answer the B6 account test, which asks when they spotted it. This is P0 and is not repeated in session.", "Mentor brief": "— what the mentor knows and must not say.\n\nThe mentor reads the scripted lines of the supervisor. The supervisor DOES NOT KNOW about the figure. The mentor must not hint, lead, or react expressively. The mentor must not raise the summary, the volumes figure, the extract or the client at any point. If the participant does not raise it, the session runs to B7 unchanged and that is a valid observation.", "The four questions": ", verbatim, and nothing else in the script is a question.\n\n1. B3 — \"How did the week go on your side?\"\n2. B4 — \"The client organization has asked for the next summary by Friday. Can you take that?\"\n3. B5 — \"Is there anything you''d want done differently on the next one?\"\n4. B6 — \"Just so I have the sequence right — when did you first see that the volumes figure came from the previous month''s extract?\"", "Mentor reference card": "— six sections, no correct answers anywhere on it.\n\n1. The four questions, verbatim, as listed above\n2. Material disclosure items — the three listed above\n3. Causal record set — the three listed above\n4. Attribution support set — the one listed above\n5. Available actions and accountable actors — as listed above, with the eligibility flags\n6. Flags table — knowledge point Wednesday; impact point Tuesday; enquiry point none; knowledge test point B6"}, "source_version_hash": "e1029a68854f1cc820b5779996110739772cc4ab7c13ff51d8065f6222b1e634"}'::jsonb from public.t3a_content_object where identifier = 'DEMO-D2-S2-001' and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = t3a_content_object.content_object_id);
insert into public.t3a_source_authorship(source_version_id, source_author_identity) select v.content_version_id, array['DEMONSTRATION_AUTHOR'] from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D2-S2-001' on conflict do nothing;
insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 1, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D2-S2-001' on conflict do nothing;
insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 2, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D2-S2-001' on conflict do nothing;
insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('DEMO-D2-S3-001', 'source'::public.t3a_content_family, 'The inherited handover pack', 'D2', 'not_loaded'::public.t3a_operational_state) on conflict do nothing;
insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"source_identifier": "DEMO-D2-S3-001", "title": "The inherited handover pack", "stage": 3, "stage_code": "S3", "demonstration": true, "serving_eligible": false, "scenario_class": "work_sample", "d2_situation_class": "SC-D2-5", "interaction_pattern_family_id": "IPF-D2-05 (derived)", "administration_form_id": "AF-S3-ASYNC-SUBMISSION", "name_clearance_claim": "CLEARED", "compatibility_class": "DEMO-ONLY", "source_sheet": {"scenario_class": "work_sample", "dimensions_in_play": "D2, sampled through the workplace demand of taking over incomplete work with a client-facing gap", "relevant_conduct": "what the plan says about who holds the acceptance criteria; the account of the pack''s state; whether the coordinator is told the section is empty; what is proposed and by whom; what date is committed", "irrelevant_conduct": "the technical merit of the plan; writing quality; the departed colleague''s conduct", "stated_standard": "\"The coordinator has asked you for a completion plan by Friday.\" Exact brief text", "permitted_administration_variance": "Extended time and assistive software permitted and recorded", "unsupported_inferences": "That the participant should have escalated; that the departed colleague was at fault; anything about the participant''s workload tolerance", "cross_context_map": "None", "min_seconds": "not_applicable, reason: asynchronous Stage", "max_seconds": "not_applicable, reason: asynchronous Stage", "compatibility_class": "DEMO-ONLY", "randomization_seed": "Instance-level", "item_ownership_state": "held_by_participant", "knowledge_point": "On receiving the handover pack. Exact text: \"You were given a handover pack... One is empty\"", "impact_point": "When the client organization signs against the acceptance criteria", "enquiry_point": "The coordinator''s request for a completion plan", "knowledge_test_point": "not_applicable, reason: CE-D2-09 IS NOT IN LAUNCH DESIGN AT STAGE 3. The asynchronous form creates no point at which the established knowledge can be put to the participant and a response observed", "affected_party": "the coordinator", "available_actions": "(a) state the empty section in the plan; evidenced in the submitted work, q_d2_02b_eligible true; (b) name a date for the acceptance criteria; evidenced in the submitted work, q_d2_02b_eligible true; (c) request input from a named role; evidenced in the submitted work, q_d2_02b_eligible true", "material_disclosure_items": "(a) that the acceptance criteria section is empty; (b) that the client organization signs against it; (c) that two further sections are incomplete", "causal_record_set": "(a) the pack was handed over with six sections; (b) three complete, two partial, one empty; (c) the colleague has left the delivery team", "attribution_support_set": "(a) the pack was received in that state", "accountable_actor_set": "the participant; the coordinator; the client organization", "constraint_set": "\"by Friday.\" Exact brief text", "route_observation_basis": "Evidenced in the submitted work or the review exchange", "d2_situation_class": "SC-D2-5"}, "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "The brief places the work with the participant and invites a statement of state"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "The plan is the action surface; available_actions are evidenced in the submission"}, {"question": "Q-D2-02b", "state": "CONDITIONAL", "basis": "Served on Q-D2-02 A1. available_actions is non-empty"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "affected_party is the addressee of the plan"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served on Q-D2-03a A1, A2 or A4"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "knowledge_point and impact_point are both established"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "Served on Q-D2-04a A1 or A2"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set is non-empty"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served on Q-D2-05a A2"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "attribution_support_set is non-empty"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "Served on Q-D2-06a A1 or A2"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "The brief asks what will be done"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "Served on Q-D2-07a A1"}, {"question": "Q-D2-08a", "state": "NOT SERVED", "basis": "CE-D2-08 IS NOT IN LAUNCH DESIGN AT STAGE 3. No answer row, no missing-state code"}, {"question": "Q-D2-09", "state": "NOT SERVED", "basis": "CE-D2-09 IS NOT IN LAUNCH DESIGN AT STAGE 3. No answer row, no missing-state code"}], "script": null, "reveals": [], "text_blocks": {"The brief as the participant meets it": "You have taken over a piece of work from a colleague who has left the delivery team. You were given a handover pack.\nThe pack has six sections. Three are complete. Two are partly written. One is empty. The empty section is the acceptance criteria, and the client organization signs against it.\nThe coordinator has asked you for a completion plan by Friday.\nProduce a completion plan. Say what state the work is in, what you will do, by when, and what you need from anyone else."}, "narrative": {"The brief as the participant meets it": "> You have taken over a piece of work from a colleague who has left the delivery team. You were given a handover pack.\n>\n> The pack has six sections. Three are complete. Two are partly written. One is empty. The empty section is the acceptance criteria, and the client organization signs against it.\n>\n> The coordinator has asked you for a completion plan by Friday.\n>\n> Produce a completion plan. Say what state the work is in, what you will do, by when, and what you need from anyone else.", "Submission": "An asynchronous written submission. `min_seconds`, `max_seconds` and `mentor_script` are NULL for Stage 3 and null is not an error.\n\nEleven required provenance fields at submission, with `prior_version_ref` a twelfth required ONLY on a resubmission and ABSENT on a first. Three declarations with controlled verbatim wording: authorship, tooling, third-party material. AI_USE_DECLARATION_REQUIRED is in force for this fixture — a missing tooling declaration refuses and logs.", "The mentor''s factual capture": "The mentor does not run a session. The mentor reads the submission and records determinations against it. Where the submission does not address a served question, the mentor records the controlled missing-state code and NEVER picks the nearest line."}, "source_version_hash": "6a2698f33ca2fafdd58bf6a4221c61c544f87002dab81ce0a1cadc61d4b3d3b5"}'::jsonb from public.t3a_content_object where identifier = 'DEMO-D2-S3-001' and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = t3a_content_object.content_object_id);
