insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('DEMO-D2-S4-001', 'source'::public.t3a_content_family, 'The missed milestone review', 'D2', 'not_loaded'::public.t3a_operational_state) on conflict do nothing;
insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"source_identifier": "DEMO-D2-S4-001", "title": "The missed milestone review", "stage": 4, "stage_code": "S4", "demonstration": true, "serving_eligible": false, "scenario_class": "team_simulation", "d2_situation_class": "SC-D2-4", "interaction_pattern_family_id": "IPF-D2-04 (derived)", "administration_form_id": "AF-S4-GROUP-ROUND", "name_clearance_claim": "CLEARED", "compatibility_class": "DEMO-ONLY", "source_sheet": {"scenario_class": "team_simulation", "dimensions_in_play": "D2, sampled through the workplace demand of accounting for a strand''s contribution to a shared failure in front of peers", "relevant_conduct": "what P-OBS stated about holding the strand''s delay; what was said to the coordinator; the account of cause; whether other strands were named; the recovery commitment; the answer at B6", "irrelevant_conduct": "the conduct of CP-1, CP-2 or CP-3, which is scripted and is never observed, recorded or rendered; P-OBS''s speaking style or assertiveness", "stated_standard": "\"The client organization wants a recovery date by tomorrow.\" Exact text at B4", "permitted_administration_variance": "Pronunciation only. Accommodations affecting turn order or response window are recorded and trigger timing_not_comparable", "unsupported_inferences": "That P-OBS caused the milestone slip; that not having told anyone on the Monday was concealment; anything about the other strands'' actual performance", "cross_context_map": "None", "min_seconds": "900", "max_seconds": "1500", "compatibility_class": "DEMO-ONLY", "randomization_seed": "Instance-level", "item_ownership_state": "held_by_participant", "knowledge_point": "The Monday of that week. Exact pre-brief text: \"You knew on the Monday of that week that it would be late, because the second extract had not arrived\"", "impact_point": "The milestone date", "enquiry_point": "B3, when the facilitator turns to data preparation", "knowledge_test_point": "B6", "affected_party": "the coordinator", "available_actions": "(a) state the strand''s delay in the round at B2 before being asked; performable_in_session true, q_d2_02b_eligible true; (b) state the Monday knowledge at B3; performable_in_session true, q_d2_02b_eligible true; (c) name a recovery date at B4; performable_in_session true, q_d2_02b_eligible true", "material_disclosure_items": "(a) that the data preparation strand finished four days late; (b) that the delay was known on the Monday; (c) that the second extract had not arrived", "causal_record_set": "(a) the second extract had not arrived; (b) the strand finished four days late; (c) the overall milestone went nine days over", "attribution_support_set": "(a) the second extract had not arrived. NOTE: CP-1''s statement that the build strand was held up by data preparation is A PRESSURE ASSERTION MADE BY A CHARACTER and is NOT a supported attribution. It must not be selectable at Q-D2-06b", "accountable_actor_set": "P-OBS; the coordinator; the client organization", "constraint_set": "\"a recovery date by tomorrow.\" Exact text at B4", "d2_situation_class": "SC-D2-4"}, "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "P-OBS ran the strand and B3 creates the opportunity"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "Three in-session performable acts"}, {"question": "Q-D2-02b", "state": "CONDITIONAL", "basis": "Served on Q-D2-02 A1"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "affected_party is in the room"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served on Q-D2-03a A1, A2 or A4"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "Both points established"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "Served on Q-D2-04a A1 or A2. enquiry_point is B3, so both A1 and A2 are reachable — B2 is before the enquiry, B3 onward is after"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set is non-empty"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served on Q-D2-05a A2"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "attribution_support_set is non-empty"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "Served on Q-D2-06a A1 or A2. Only the extract item is selectable; the UNSUPPORTED_ATTRIBUTION selection carries everything else"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "B5 creates the remedy opportunity"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "Served on Q-D2-07a A1"}, {"question": "Q-D2-08a", "state": "DIRECT", "basis": "B4 requests a commitment against a stated constraint"}, {"question": "Q-D2-09", "state": "DIRECT", "basis": "knowledge_test_point exists at B6"}], "script": [{"beat": "B1", "type": "SAY", "verbatim_text": "\"Thanks everyone. The integration milestone went nine days over. This is a short review to get the sequence straight, not to allocate fault. I''ll go round in this order — build strand, test strand, schedule, then data preparation. Two minutes each.\"", "capture": "None. B1 IS NEVER A QUESTION"}, {"beat": "B2", "type": "ROUND", "verbatim_text": "CP-1, CP-2 and CP-3 give their positions in the stated order. The facilitator does not address P-OBS", "capture": "C1, C3a, C6a where P-OBS speaks out of turn"}, {"beat": "B3", "type": "ASK 1", "verbatim_text": "\"Data preparation — your turn. How did that strand run?\"", "capture": "C1, C2, C3a, C4a, C5a, C6a"}, {"beat": "B4", "type": "ASK 2", "verbatim_text": "\"The client organization wants a recovery date by tomorrow. Can data preparation commit to one?\"", "capture": "C8a"}, {"beat": "B5", "type": "ASK 3", "verbatim_text": "\"What would you change for the next milestone, and who would do it?\"", "capture": "C7a, C7b, C2b"}, {"beat": "B6", "type": "ASK 4", "verbatim_text": "\"Just so the sequence is right — when did you first know the second extract had not arrived?\"", "capture": "C9, C5a, C5b, C6b"}, {"beat": "B7", "type": "SAY", "verbatim_text": "\"That''s the review. Thank you all.\"", "capture": "None"}], "reveals": [], "text_blocks": {"Pre-brief — P-OBS": "The delivery team missed the integration milestone by nine days. The coordinator has called a short review.\nYou ran the data preparation strand. Your strand finished four days late. You knew on the Monday of that week that it would be late, because the second extract had not arrived.\nYou have not told anyone that you knew on the Monday.", "Pre-brief — CP-1": "You ran the build strand. State that your strand was held up waiting for data preparation. Do not depart from this position.", "Pre-brief — CP-2": "You ran the test strand. State that you had three days instead of seven and could not cover the full set. Do not depart from this position.", "Pre-brief — CP-3": "You coordinated the schedule. State that the milestone date was fixed by the client organization and was not moveable. Do not depart from this position.", "Facilitator card": "You are facilitating the session AND observing P-OBS only.\nAt B1 you state the speaking order aloud: CP-1, CP-2, CP-3, then P-OBS. Stating the order means that waiting is not itself a choice made under uncertainty.\nDuring the B2 round you MUST NOT look at, gesture towards, or address P-OBS. Not once.\nYou read the scripted text verbatim. You do not react expressively to anything anyone says."}, "narrative": {"Model": "ONE OBSERVED PARTICIPANT (P-OBS) and THREE CO-PARTICIPANTS (CP-1, CP-2, CP-3) who are role players and are NOT observed. One facilitator. ONE OBSERVATION RECORD IS WRITTEN, for P-OBS only. A Stage 4 group participation record is required for all four before entry.", "Pre-brief — P-OBS": "> The delivery team missed the integration milestone by nine days. The coordinator has called a short review.\n>\n> You ran the data preparation strand. Your strand finished four days late. You knew on the Monday of that week that it would be late, because the second extract had not arrived.\n>\n> You have not told anyone that you knew on the Monday.", "Pre-brief — CP-1": "> You ran the build strand. State that your strand was held up waiting for data preparation. Do not depart from this position.", "Pre-brief — CP-2": "> You ran the test strand. State that you had three days instead of seven and could not cover the full set. Do not depart from this position.", "Pre-brief — CP-3": "> You coordinated the schedule. State that the milestone date was fixed by the client organization and was not moveable. Do not depart from this position.\n\nEach co-participant is told in writing that they are not observed.", "Facilitator card": "> You are facilitating the session AND observing P-OBS only.\n>\n> At B1 you state the speaking order aloud: CP-1, CP-2, CP-3, then P-OBS. Stating the order means that waiting is not itself a choice made under uncertainty.\n>\n> During the B2 round you MUST NOT look at, gesture towards, or address P-OBS. Not once.\n>\n> You read the scripted text verbatim. You do not react expressively to anything anyone says.", "Facilitator reference card": "— six sections, no correct answers. Same structure as Section 10.2, with the addition that the flags table marks enquiry_point at B3, which is what makes Q-D2-04b answerable in both directions in this fixture.", "What this fixture proves": "Q-D2-04b is reachable at both values here and only at A1 in DEMO-D2-S2-001, because the two sources place the enquiry point differently. A build that hard-codes either behavior passes one fixture and fails the other."}, "source_version_hash": "13a6e5845c31d454163716b0954eb8cd3fce99c1727a6d1c722c86a035cdc146"}'::jsonb from public.t3a_content_object where identifier = 'DEMO-D2-S4-001' and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = t3a_content_object.content_object_id);
